The code below generalizes this to d dimensions and runs in O(n \cdot 2^d \cdot d).

[CODE_BLOCK lang=cpp]
long long ans = 0;
for (int msk = 0; msk < (1 << d); msk++) {
long long mx = LLONG_MIN, mn = LLONG_MAX;
for (int i = 0; i < n; i++) {
    long long cur = 0;
    for (int j = 0; j < d; j++) {
        if (msk & (1 << j)) cur += p[i][j];
        else cur -= p[i][j];
    }
    mx = max(mx, cur);
    mn = min(mn, cur);
}
ans = max(ans, mx - mn);
}
