d[s] = 0;
set> q;
q.insert({0, s});
while (!q.empty()) {
int v = q.begin()->second;
q.erase(q.begin());

for (auto edge : adj[v]) {
    int u = edge.first;
    int w = edge.second;

    if (d[v] + w < d[u]) {
        q.erase({d[u], u});
        d[u] = d[v] + w;
        q.insert({d[u], u});
    }
}
}
