Initially you call the function `init()`, which initializes the two DSUs (creating a separate set for each vertex, and setting the size equal to one), and sets the ancestors `par`.

The main function is `add_edge(a, b)`, which processes and adds a new edge.

[CODE_BLOCK lang=cpp]
vector<int> par, dsu_2ecc, dsu_cc, dsu_cc_size;
int bridges;
int lca_iteration;
vector<int> last_visit;

void init(int n) {
par.resize(n);
dsu_2ecc.resize(n);
dsu_cc.resize(n);
dsu_cc_size.resize(n);
lca_iteration = 0;
last_visit.assign(n, 0);
for (int i=0; i<n; ++i) {
    dsu_2ecc[i] = i;
    dsu_cc[i] = i;
    dsu_cc_size[i] = 1;
    par[i] = -1;
}
bridges = 0;
}

int find_2ecc(int v) {
if (v == -1)
    return -1;
return dsu_2ecc[v] == v ? v : dsu_2ecc[v] = find_2ecc(dsu_2ecc[v]);
}

int find_cc(int v) {
v = find_2ecc(v);
return dsu_cc[v] == v ? v : dsu_cc[v] = find_cc(dsu_cc[v]);
}

void make_root(int v) {
int root = v;
int child = -1;
while (v != -1) {
    int p = find_2ecc(par[v]);
    par[v] = child;
    dsu_cc[v] = root;
    child = v;
    v = p;
}
dsu_cc_size[root] = dsu_cc_size[child];
}

void merge_path (int a, int b) {
++lca_iteration;
vector<int> path_a, path_b;
int lca = -1;
while (lca == -1) {
    if (a != -1) {
        a = find_2ecc(a);
        path_a.push_back(a);
        if (last_visit[a] == lca_iteration){
            lca = a;
            break;
            }
        last_visit[a] = lca_iteration;
        a = par[a];
    }
    if (b != -1) {
        b = find_2ecc(b);
        path_b.push_back(b);
        if (last_visit[b] == lca_iteration){
            lca = b;
            break;
            }
        last_visit[b] = lca_iteration;
        b = par[b];
    }

}

}

for (int v : path_a) {
    dsu_2ecc[v] = lca;
    if (v == lca)
        break;
    --bridges;
}
for (int v : path_b) {
    dsu_2ecc[v] = lca;
    if (v == lca)
        break;
    --bridges;
}
}

void add_edge(int a, int b) {
a = find_2ecc(a);
b = find_2ecc(b);
if (a == b)
    return;

int ca = find_cc(a);
int cb = find_cc(b);

if (ca != cb) {
    ++bridges;
    if (dsu_cc_size[ca] > dsu_cc_size[cb]) {
        swap(a, b);
        swap(ca, cb);
    }
    make_root(a);
    par[a] = dsu_cc[a] = b;
    dsu_cc_size[cb] += dsu_cc_size[a];
} else {
    merge_path(a, b);
}
}
[/CODE_BLOCK]

$\mathtt{low}[v] = \min \left\{
\begin{array}{l}
\mathtt{tin}[v] \\
\mathtt{tin}[p]  &\text{ for all }p\text{ for which }(v, p)\text{ is a back edge} \\
\mathtt{low}[to] &\text{ for all }to\text{ for which }(v, to)\text{ is a tree edge}
\end{array}
\right\}

Now, there is a back edge from vertex v or one of its descendants to one of its ancestors if and only if vertex v has a child to for which \mathtt{low}[to] \leq \mathtt{tin}[v]. If \mathtt{low}[to] = \mathtt{tin}[v], the back edge comes directly to v, otherwise it comes to one of the ancestors of v.

## Implementation

The implementation needs to distinguish three cases: when we go down the edge in DFS tree, when we find a back edge to an ancestor of the vertex and when we return to a parent of the vertex. These are the cases:

- \mathtt{visited}[to] = false - the edge is part of DFS tree;
- \mathtt{visited}[to] = true && to \neq parent - the edge is back edge to one of the ancestors;
- to = parent - the edge leads back to parent in DFS tree.

To implement this, we need a depth first search function which accepts the parent vertex of the current node.

For the cases of multiple edges, we need to be careful when ignoring the edge from the parent. To solve this issue, we can add a flag `parent_skipped` which will ensure we only skip the parent once.

```{.cpp file=bridge_searching_offline}
void IS_BRIDGE(int v,int to); // some function to process the found bridge
int n; // number of nodes
vector<vector<int>> adj; // adjacency list of graph

vector<bool> visited;
vector<int> tin, low;
int timer;

vector<bool> visited;
vector<int> tin, low;
int timer;

void dfs(int v, int p = -1) {
visited[v] = true;
tin[v] = low[v] = timer++;
bool parent_skipped = false;
for (int to : adj[v]) {
    if (to == p && !parent_skipped) {
        parent_skipped = true;
        continue;
    }
    if (visited[to]) {
        low[v] = min(low[v], tin[to]);
    } else {
        dfs(to, v);
        low[v] = min(low[v], low[to]);
        if (low[to] > tin[v])
            IS_BRIDGE(v, to);
    }
}
}

void find_bridges() {
timer = 0;
visited.assign(n, false);
tin.assign(n, -1);
low.assign(n, -1);
for (int i = 0; i < n; ++i) {
    if (!visited[i])
        dfs(i);
}
}
```

Main function is `find_bridges`; it performs necessary initialization and starts depth first search in each connected component of the graph.

Function `IS_BRIDGE(a, b)` is some function that will process the fact that edge (a, b)$ is a bridge, for example, print it.

## Implementation

Here's an implementation of centroid decomposition solving a specific problem: **counting all paths in the tree with length exactly K**.

In this problem, we're given a tree with N vertices and need to count how many paths have exactly K edges. A path is defined by two distinct vertices.

```{.cpp file=centroid_decomposition}
const int MAXN = 1e5;
vector<int> adj[MAXN];
bool removed[MAXN];
int subtree_size[MAXN];
int K;  // Target path length
long long answer = 0;  // Count of paths with length K

int get_subtree_size(int v, int p = -1) {
subtree_size[v] = 1;
for (int u : adj[v]) {
    if (u == p || removed[u]) continue;
    subtree_size[v] += get_subtree_size(u, v);
}
return subtree_size[v];
}

int get_centroid(int v, int tree_size, int p = -1) {
for (int u : adj[v]) {
    if (u == p || removed[u]) continue;
    if (subtree_size[u] * 2 > tree_size)
        return get_centroid(u, tree_size, v);
}
return v;
}

void get_distances(int v, int p, int dist, vector<int>& distances) {
if (dist > K) return;
distances.push_back(dist);
for (int u : adj[v]) {
    if (u == p || removed[u]) continue;
    get_distances(u, v, dist + 1, distances);
}
}

void process_centroid(int centroid) {
unordered_map<int, int> all_distances;
all_distances[0] = 1;

for (int u : adj[centroid]) {
    if (removed[u])
        continue;

    vector<int> current_distances;
    get_distances(u, centroid, 1, current_distances);

vector<int> current_distances;
    get_distances(u, centroid, 1, current_distances);

    for (int d : current_distances) {
        if (K - d >= 0) {
            answer += (all_distances[K - d] ? all_distances[K - d] : 0);
        }
    }

    for (int d : current_distances) {
        if (all_distances.find(d) == all_distances.end())
            all_distances[d] = 0;
        all_distances[d]++;
    }
}
}

void decompose(int v) {
int tree_size = get_subtree_size(v);
int centroid = get_centroid(v, tree_size);

process_centroid(centroid);

removed[centroid] = true;

process_centroid(centroid);

removed[centroid] = true;

for (int u : adj[centroid]) {
    if (!removed[u]) {
        decompose(u);
    }
}
}

### Building the Centroid Tree

If you need to build an explicit centroid tree structure (useful for answering queries):
