    for (Edge e : adj[u]) {
        if (d[e.to] > d[u] + e.w) {
            d[e.to] = d[u] + e.w;
            p[e.to] = u;
            if (m[e.to] == 2) {
                m[e.to] = 1;
                q.push_back(e.to);
            } else if (m[e.to] == 0) {
                m[e.to] = 1;
                q.push_front(e.to);
            }
        }
    }
}
