int maxflow(int s, int t) {
int flow = 0;
vector<int> parent(n);
int new_flow;

while (new_flow = bfs(s, t, parent)) {
    flow += new_flow;
    int cur = t;
    while (cur != s) {
        int prev = parent[cur];
        capacity[prev][cur] -= new_flow;
        capacity[cur][prev] += new_flow;
        cur = prev;
    }
}

return flow;
}
