But we can write the same algorithm in the non-recursive version:

[CODE_BLOCK lang=nohighlight]
stack St;
put start vertex in St;
until St is empty
  let V be the value at the top of St;
  if degree(V) = 0, then
add V to the answer;
remove V from the top of St;
  otherwise
find any edge coming out of V;
remove it from the graph;
put the second end of this edge in St;
[/CODE_BLOCK]

It is easy to check the equivalence of these two forms of the algorithm. However, the second form is obviously faster, and the code will be much more efficient.

Notice that we use an adjacency matrix in this problem.
Also this implementation handles finding the next with brute-force, which requires to iterate over the complete row in the matrix over and over.
A better way would be to store the graph as an adjacency list, and remove edges in O(1) and mark the reversed edges in separate list.
This way we can achieve an O(N) algorithm.

[CODE_BLOCK lang=cpp]
int main() {
int n;
vector<vector<int>> g(n, vector<int>(n));
// reading the graph in the adjacency matrix

vector<int> deg(n);
for (int i = 0; i < n; ++i) {
    for (int j = 0; j < n; ++j)
        deg[i] += g[i][j];
}

int first = 0;
while (first < n && !deg[first])
    ++first;
if (first == n) {
    cout << -1;
    return 0;
}

int v1 = -1, v2 = -1;
bool bad = false;
for (int i = 0; i < n; ++i) {
    if (deg[i] & 1) {
        if (v1 == -1)
            v1 = i;
        else if (v2 == -1)
            v2 = i;
        else
            bad = true;
    }
}

if (v1 != -1)
    ++g[v1][v2], ++g[v2][v1];

if (v1 != -1)
    ++g[v1][v2], ++g[v2][v1];

stack<int> st;
st.push(first);
vector<int> res;
while (!st.empty()) {
    int v = st.top();
    int i;
    for (i = 0; i < n; ++i)
        if (g[v][i])
            break;
    if (i == n) {
        res.push_back(v);
        st.pop();
    } else {
        --g[v][i];
        --g[i][v];
        st.push(i);
    }
}

if (v1 != -1) {
    for (size_t i = 0; i + 1 < res.size(); ++i) {
        if ((res[i] == v1 && res[i + 1] == v2) ||
            (res[i] == v2 && res[i + 1] == v1)) {
            vector<int> res2;
            for (size_t j = i + 1; j < res.size(); ++j)
                res2.push_back(res[j]);
            for (size_t j = 1; j <= i; ++j)
                res2.push_back(res[j]);
            res = res2;
            break;
        }
    }
}

for (int i = 0; i < n; ++i) {
    for (int j = 0; j < n; ++j) {
        if (g[i][j])
            bad = true;
    }
}

if (bad) {
    cout << -1;
} else {
    for (int x : res)
        cout << x << " ";
}
}
