vector<bool> killed(n, false);
for (int i = 0; i < n; i++) {
    degree[i] = adj[i].size();
    if (degree[i] == 1)
        leafs.insert(i);
}

vector<int> code(n - 2);
for (int i = 0; i < n - 2; i++) {
    int leaf = *leafs.begin();
    leafs.erase(leafs.begin());
    killed[leaf] = true;

    int v;
    for (int u : adj[leaf]) {
        if (!killed[u])
            v = u;
    }

    code[i] = v;
    if (--degree[v] == 1)
        leafs.insert(v);
}

return code;
}

