void dfs(int v, const graph& g, const graph& edge_ids, int cur_h = 1) {
h[v] = cur_h;
dfs_list.push_back(v);
for (size_t i = 0; i < g[v].size(); ++i) {
    if (h[g[v][i]] == -1) {
        edges_list.push_back(edge_ids[v][i]);
        dfs(g[v][i], g, edge_ids, cur_h + 1);
        edges_list.push_back(edge_ids[v][i]);
        dfs_list.push_back(v);
