It is easy to see that thanks to memoization of the suffix links and transitions,
the total time for finding all suffix links and transitions will be linear.

After we processed the entire string, some operators might still be in the stack, so we execute them.

Here is the implementation of this method for the four operators + - * /:

```{.cpp file=expression_parsing_simple}
bool delim(char c) {
return c == ' ';
}

bool is_op(char c) {
return c == '+' || c == '-' || c == '*' || c == '/';
}

int priority (char op) {
if (op == '+' || op == '-')
    return 1;
if (op == '*' || op == '/')
    return 2;
return -1;
}

void process_op(stack<int>& st, char op) {
int r = st.top(); st.pop();
int l = st.top(); st.pop();
switch (op) {
    case '+': st.push(l + r); break;
    case '-': st.push(l - r); break;
    case '*': st.push(l * r); break;
    case '/': st.push(l / r); break;
}
}

int evaluate(string& s) {
stack<int> st;
stack<char> op;
for (int i = 0; i < (int)s.size(); i++) {
    if (delim(s[i]))
        continue;

if (s[i] == '(') {
        op.push('(');
    } else if (s[i] == ')') {
        while (op.top() != '(') {
            process_op(st, op.top());
            op.pop();
        }
        op.pop();
    } else if (is_op(s[i])) {
        char cur_op = s[i];
        while (!op.empty() && priority(op.top()) >= priority(cur_op)) {
            process_op(st, op.top());
            op.pop();
        }
        op.push(cur_op);
    } else {
        int number = 0;
        while (i < (int)s.size() && isalnum(s[i]))
            number = number * 10 + s[i++] - '0';
        --i;
        st.push(number);

number = number * 10 + s[i++] - '0';
        --i;
        st.push(number);
    }
}

while (!op.empty()) {
    process_op(st, op.top());
    op.pop();
}
return st.top();
}

