### Solution - Counting Divisors

The most straightforward solution is just to do what the problem asks us to do -
for each x, find the number of divisors of x in \mathcal{O}(\sqrt x) time.

[CODE_BLOCK lang=cpp]
#include <iostream>

using namespace std;

int main() {
	int n;
	cin >> n;
	for (int q = 0; q < n; q++) {
		int x;
		int div_num = 0;
		cin >> x;
		for (int i = 1; i * i <= x; i++) {
			if (x % i == 0) { div_num += i * i == x ? 1 : 2; }
		}
		cout << div_num << '\n';
	}
}
[/CODE_BLOCK]

Using this method gives us the following code:

[CODE_BLOCK lang=cpp]
#include <iostream>

using namespace std;

const int MAX_N = 1e6;
// max_div[i] contains the largest prime that goes into i
int max_div[MAX_N + 1];

int main() {
	for (int i = 2; i <= MAX_N; i++) {
		if (max_div[i] == 0) {
			for (int j = i; j <= MAX_N; j += i) { max_div[j] = i; }
		}
	}

	int n;
	cin >> n;

int n;
	cin >> n;

	for (int i = 0; i < n; i++) {
		int x;
		cin >> x;
		int div_num = 1;
		while (x != 1) {
			/*
			 * get the largest prime that can divide x and see
			 * how many times it goes into x (stored in count)
			 */
			int prime = max_div[x];
			int count = 0;
			while (x % prime == 0) {
				count++;
				x /= prime;
			}
			div_num *= count + 1;
		}
		cout << div_num << '\n';
	}
}
[/CODE_BLOCK]

[CODE_BLOCK lang=cpp]
int phi(int n) {
	int ans = n;
	for (int p = 2; p * p <= n; p++) {
		if (n % p == 0) {
			while (n % p == 0) { n /= p; }
			ans -= ans / p;
		}
	}
	if (n > 1) { ans -= ans / n; }
	return ans;
}
[/CODE_BLOCK]

Usually in problems we need to precompute the totient of all numbers between 1 and n, then factorizing is not efficient. The idea is the same as the
Sieve of Eratosthenes. Since it's almost the same with the Sieve of Eratosthenes the time complexity will be: \mathcal{O}(N\log\log{N}).

[CODE_BLOCK lang=cpp]
void precompute() {
	for (int i = 1; i < MAX_N; i++) { phi[i] = i; }
	for (int i = 2; i < MAX_N; i++) {
		// If i is prime
		if (phi[i] == i) {
			for (int j = i; j < MAX_N; j += i) { phi[j] -= phi[j] / i; }
		}
	}
}
[/CODE_BLOCK]

\text{ans}[n] = \sum_{j=1}^{n} (f(j) - j).

The total complexity of this precomputation is bounded by the harmonic series sum:
\sum_{i=1}^{N} \frac{N}{i} \approx N \ln N$

[CODE_BLOCK lang=cpp]
#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const int MAX_N = 1e6;

ll phi[MAX_N + 1];
ll f[MAX_N + 1];
ll sum[MAX_N + 1];

int main() {
	// compute phi using sieve
	for (int i = 1; i <= MAX_N; i++) phi[i] = i;

	for (int i = 2; i <= MAX_N; i++)
		if (phi[i] == i)
			for (int j = i; j <= MAX_N; j += i) phi[j] -= phi[j] / i;

// compute f[j]
	for (int i = 1; i <= MAX_N; i++)
		for (int j = i; j <= MAX_N; j += i) f[j] += 1LL * i * phi[j / i];

	// prefix sums for answers (remove diagonal a=b)
	for (int i = 1; i <= MAX_N; i++) sum[i] = sum[i - 1] + f[i] - i;

	int n;
	while (cin >> n) {
		if (n == 0) break;
		cout << sum[n] << '\n';
	}

	return 0;
}
[/CODE_BLOCK]

### Solution

Let dp[S][i] be the number of routes that visit all the cities in the subset
S and end at city i. The transitions will then be:

$
dp[S][i] = \sum_{x \in adj[i]} dp[S  \setminus \{i\}][x] \text{ if x \in S}

where S  \setminus \{i\} is the subset S without city i.

**Time Complexity:** \mathcal{O}(2^N \cdot N^2)

[CODE_BLOCK lang=cpp]
#include <bits/stdc++.h>
using namespace std;

using ll = long long;

const int MAX_N = 20;
const ll MOD = (ll)1e9 + 7;

ll dp[1 << MAX_N][MAX_N];
// come_from[i] contains the cities that can fly to i
vector<int> come_from[MAX_N];

int main() {
	int city_num;
	int flight_num;
	cin >> city_num >> flight_num;
	for (int f = 0; f < flight_num; f++) {
		int start, end;
		cin >> start >> end;
		come_from[--end].push_back(--start);
	}

	dp[1][0] = 1;
	for (int s = 2; s < 1 << city_num; s++) {
		// only consider subsets that have the first city
		if ((s & (1 << 0)) == 0) continue;
		// also only consider subsets with the last city if it's the full subset
		if ((s & (1 << (city_num - 1))) && s != ((1 << city_num) - 1)) continue;

		for (int end = 0; end < city_num; end++) {
			if ((s & (1 << end)) == 0) continue;

for (int end = 0; end < city_num; end++) {
			if ((s & (1 << end)) == 0) continue;

			// the subset that doesn't include the current end
			int prev = s - (1 << end);
			for (int j : come_from[end]) {
				if ((s & (1 << j))) {
					dp[s][end] += dp[prev][j];
					dp[s][end] %= MOD;
				}
			}
		}
	}
	cout << dp[(1 << city_num) - 1][city_num - 1] << '\n';
}
[/CODE_BLOCK]

Given that each element can be in three possible states, our overall complexity is actually \mathcal{O}(3^N).

