	std::map<int, long long> hash_vals;
	vector<int> a(len);
	for (int &i : a) {
		std::cin >> i;
		// assign a hash value to each unique number in the array
		if (!hash_vals.count(i)) { hash_vals[i] = rng(); }
	}
	vector<int> b(len);
	for (int &i : b) {
		std::cin >> i;
		if (!hash_vals.count(i)) { hash_vals[i] = rng(); }
