		if (i > 0) { a_xor[i] ^= a_xor[i - 1]; }
	}

	seen.clear();
	// do the same thing for b
	vector<long long> b_xor(len);
	for (int i = 0; i < len; i++) {
		if (!seen.count(b[i])) {
			b_xor[i] = hash_vals[b[i]];
			seen.insert(b[i]);
		}
		if (i > 0) { b_xor[i] ^= b_xor[i - 1]; }
	}

