const int N = 2e5;

vector<int> gen_multiples(int x) {
	int cur = 1, rem = 1;
	vector<int> res;
	for (int i = 1; i <= N; i++) {
		assert(1 <= cur && cur <= 1e9);
		res.push_back(cur);
		cur += x;
		if (cur > 1e9) {
			++rem;
			cur = rem;
		}
	}
	return res;
}

