		std::cin >> a >> b >> c;
		a--;
		b--;
		if (c < min_dist[a][b]) { min_dist[a][b] = min_dist[b][a] = c; }
	}

	// Floyd-Warshall algorithm
	for (int k = 0; k < n; k++) {
		for (int i = 0; i < n; i++) {
			for (int j = i + 1; j < n; j++) {
				long long new_dist = min_dist[i][k] + min_dist[k][j];
				if (new_dist < min_dist[i][j]) {
					min_dist[i][j] = min_dist[j][i] = new_dist;
				}
			}
